input.content:
// Throwaway probe of MPT edge-case behaviour on testnet, using faucet accounts only.
import { Client } from 'xrpl'
const c = new Client('wss://s.altnet.rippletest.net:51233')
await c.connect()
const [{ wallet: iss }, { wallet: h1 }, { wallet: h2 }] = await Promise.all([c.fundWallet(), c.fundWallet(), c.fundWallet()])

async function tx(w, t, label) {
  try {
    const r = await c.submitAndWait({ ...t, Account: w.address }, { wallet: w, autofill: true })
    console.log(label.padEnd(55), r.result.meta.TransactionResult)
    return r
  } catch (e) {
    console.log(label.padEnd(55), 'THROW', e.data?.error ?? e.message)
  }
}
async function mpt(acct) {
  const r = await c.request({ command: 'account_objects', account: acct, type: 'mptoken', ledger_index: 'validated' })
  const o = r.result.account_objects[0]
  return o ? `amt=${o.MPTAmount ?? 0} flags=${o.Flags}` : 'none'
}

const r = await tx(iss, { TransactionType: 'MPTokenIssuanceCreate', Flags: 2 | 4 | 32 | 64, AssetScale: 2 }, 'create')
const id = r.result.meta.mpt_issuance_id
console.log('id', id)
const amt = (v) => ({ mpt_issuance_id: id, value: v })
const pay = (w, d, v, l) => tx(w, { TransactionType: 'Payment', Destination: d, Amount: amt(v) }, l)
const set = (f, holder, l) => tx(iss, { TransactionType: 'MPTokenIssuanceSet', MPTokenIssuanceID: id, Flags: f, ...(holder ? { Holder: holder } : {}) }, l)

for (const h of [h1, h2]) {
  await tx(h, { TransactionType: 'MPTokenAuthorize', MPTokenIssuanceID: id }, 'holder opt-in')
}
await pay(iss, h1.address, '1000', 'pay h1 before auth (expect fail)')
for (const h of [h1, h2]) await tx(iss, { TransactionType: 'MPTokenAuthorize', MPTokenIssuanceID: id, Holder: h.address }, 'issuer auth')
await pay(iss, h1.address, '1000', 'pay h1 1000')
await pay(iss, h2.address, '1000', 'pay h2 1000')

// individual lock
await set(1, h1.address, 'lock h1')
await pay(iss, h1.address, '1', 'issuer -> locked h1')
await pay(h1, h2.address, '1', 'locked h1 -> h2')
await pay(h2, h1.address, '1', 'h2 -> locked h1')
await pay(h1, iss.address, '1', 'locked h1 -> issuer (redeem)')
await tx(iss, { TransactionType: 'Clawback', Holder: h1.address, Amount: amt('10') }, 'clawback 10 from locked h1')
await set(2, h1.address, 'unlock h1')

// global lock
await set(1, undefined, 'global lock')
await pay(iss, h1.address, '1', 'issuer -> h1 while global lock')
await pay(h1, h2.address, '1', 'h1 -> h2 while global lock')
await tx(iss, { TransactionType: 'Clawback', Holder: h1.address, Amount: amt('1') }, 'clawback 1 while global lock')
await set(2, undefined, 'global unlock')

// unauthorize with balance
await tx(iss, { TransactionType: 'MPTokenAuthorize', MPTokenIssuanceID: id, Holder: h2.address, Flags: 1 }, 'issuer unauth h2 WITH balance')
console.log('h2', await mpt(h2.address))
await pay(h1, h2.address, '1', 'h1 -> unauth h2')
await pay(h2, h1.address, '1', 'unauth h2 -> h1')
await tx(iss, { TransactionType: 'Clawback', Holder: h2.address, Amount: amt('99999999') }, 'clawback over-amount from unauth h2')
console.log('h2', await mpt(h2.address))
await set(1, h2.address, 'lock h2 (zero, unauth)')
await tx(h2, { TransactionType: 'MPTokenAuthorize', MPTokenIssuanceID: id, Flags: 1 }, 'h2 deletes own locked MPToken')
console.log('h2', await mpt(h2.address))
await tx(h2, { TransactionType: 'MPTokenAuthorize', MPTokenIssuanceID: id }, 'h2 re-opts-in')
console.log('h2', await mpt(h2.address))
await pay(h1, h2.address, '1', 'h1 -> re-created h2')
await tx(iss, { TransactionType: 'Clawback', Holder: h2.address, Amount: amt('1') }, 'clawback from zero balance')
await c.disconnect()

