export function parseLedgerAmount(value: string | undefined): bigint {
  if (value === undefined) {
    return 0n
  }
  if (!/^\d+$/.test(value)) {
    throw new Error(`Unexpected on-ledger amount ${JSON.stringify(value)}`)
  }
  return BigInt(value)
}

