  check((await send(B, addr.C, '1')) === 'tecNO_AUTH', 'B → C 1 rejected by ledger (tecNO_AUTH)')
  await expectRefusal(issuer.authorizeHolder(addr.C), 'HOLDER_BANNED', 're-approving banned C')
